const j = $input.first().json || {};
const exec = j.execution || {};
const wf = j.workflow || {};
let lead_id = null;
try {
  const m = JSON.stringify(j).match(/"lead_id"\s*:\s*(\d+)/);
  if (m) lead_id = parseInt(m[1], 10);
} catch (e) {}
const err = (exec.error && (exec.error.message || exec.error)) || j.message || 'workflow execution failed';
return [{ json: {
  lead_id: lead_id,
  stage: 'n8n:' + (exec.lastNodeExecuted || wf.name || 'unknown-node'),
  error: String(err).slice(0, 2000),
  payload: { workflow: wf.name || null, execution_id: exec.id || null, mode: exec.mode || null },
  attempts: 1
}}];
